// RFCErratumRows holds the one RFC 5545 example whose printed answer is wrong,
// as an EXPECTED-DIFFERENT row: it runs, and asserts the correct output rather
// than the printed one. RFC 5545 3.8.5.3 prints
//
//	DTSTART;TZID=America/New_York:19970902T090000
//	RRULE:FREQ=HOURLY;INTERVAL=3;UNTIL=19970902T170000Z
//	==> (September 2, 1997 EDT) 09:00,12:00,15:00
//
// but 170000Z is 13:00 EDT, so 15:00 EDT (19:00Z) is past UNTIL and no correct
// implementation emits it. This is RFC 5545 erratum 3883 (verified, 2014-02-14;
// it corrects UNTIL to 19970902T210000Z). The correct output of the rule as
// printed is 09:00 and 12:00 EDT only. rfc33b (UNTIL=190000Z) keeps the
// printed three-instance answer.
var RFCErratumRows = []Row{
	{"rfc33-hourly-until-AS-PRINTED-erratum-3883", hdr + "19970902T090000\nRRULE:FREQ=HOURLY;INTERVAL=3;UNTIL=19970902T170000Z", "19970902T0900 19970902T1200", false},
}
